<script setup lang="ts">
import{ref,watch,inject}from'vue';import{useRoute}from'vue-router';import type{TicketDetail,TicketFile}from'../ticket-api';import{useTicketWork}from'../ticket-work';import{ApiError}from'../api';import{ticketReadDenied,isObjectReadDenied}from'../ticket-access';import{reopenApi,validRound,type RoundSummary}from'../ticket-reopen-api';import{supplementApi}from'../ticket-supplement-api';import{referencedEvidence}from'../ticket-evidence';
const props=defineProps<{ticket:TicketDetail;modelValue:string[]}>(),emit=defineEmits<{ 'update:modelValue':[ids:string[]];files:[files:TicketFile[]];busy:[value:boolean] }>(),route=useRoute(),work=useTicketWork(()=>route.fullPath),deny=inject(ticketReadDenied,undefined),rounds=ref<RoundSummary[]>([]),selected=ref(''),files=ref<TicketFile[]>([]),known=ref<TicketFile[]>([]),roundPage=ref(1),roundTotal=ref(0),page=ref(1),total=ref(0);
const stamp=()=>JSON.stringify([props.ticket.id,props.ticket.roundId,props.ticket.rowVersion,props.ticket.assignment?.assignmentId]);
watch(()=>work.busy.value,value=>emit('busy',value),{immediate:true});
function clear(reset=false){files.value=[];total.value=0;if(reset){known.value=[];emit('files',[])}}
watch(selected,()=>{work.begin().finish();clear()},{flush:'sync'});
async function loadRounds(next=1){rounds.value=[];selected.value='';clear();const expected=stamp(),scope=work.begin(()=>stamp()===expected);try{const r=await reopenApi.rounds(props.ticket.id,next);if(!scope.current())return;if(!Array.isArray(r.items)||r.items.some(r=>!validRound(r,props.ticket.id)))throw new ApiError(503,'ROUND_PROJECTION_INVALID','证据轮次目录无法确认');rounds.value=r.items;roundTotal.value=r.total;roundPage.value=r.page}catch(e){if(scope.current()&&isObjectReadDenied(e))deny?.();work.fail(e,scope)}finally{scope.finish()}}
async function loadFiles(next=1){if(!selected.value||!rounds.value.some(r=>r.roundId===selected.value))return;const expected=stamp(),chosen=selected.value,scope=work.begin(()=>stamp()===expected&&selected.value===chosen);clear();try{const r=await supplementApi.history(props.ticket.id,next,chosen);if(!scope.current())return;files.value=referencedEvidence(r.items,props.ticket,chosen).filter(f=>!props.ticket.attachments.some(a=>a.fileId===f.fileId));const pool=new Map(known.value.map(f=>[f.fileId,f]));for(const f of files.value){const old=pool.get(f.fileId);if(old&&(old.sha256!==f.sha256||old.size!==f.size))throw new ApiError(503,'EVIDENCE_PROJECTION_INVALID','已引用附件摘要发生矛盾');pool.set(f.fileId,f)}known.value=[...pool.values()];emit('files',known.value);total.value=r.total;page.value=r.page}catch(e){if(scope.current()&&isObjectReadDenied(e))deny?.();work.fail(e,scope)}finally{scope.finish()}}
function select(id:string,checked:boolean){emit('update:modelValue',checked?[...new Set([...props.modelValue,id])]:props.modelValue.filter(f=>f!==id))}
watch(stamp,()=>{work.begin().finish();selected.value='';rounds.value=[];clear(true)});
</script>
<template><details class="referenced-evidence"><summary>显式选择本单其他已引用的公开补充附件</summary><p>原报修附件可直接选择；此处只查既有公开引用，不自动继承旧方案、不上传或复制文件，合计最多5份。查询和提交都按当前对象权限核验。</p><el-button :disabled="work.busy.value" @click="loadRounds()">查询可读轮次</el-button><el-pagination v-if="rounds.length" :current-page="roundPage" :total="roundTotal" :page-size="20" layout="prev, pager, next" @current-change="loadRounds"/><label v-if="rounds.length">证据来源轮次<select v-model="selected" aria-label="证据来源轮次"><option value="">请选择轮次</option><option v-for="r in rounds" :key="r.roundId" :value="r.roundId">第{{r.roundNo}}轮 · {{r.current?'当前':'历史'}}</option></select></label><el-button v-if="selected" :disabled="work.busy.value" @click="loadFiles()">查询该轮已引用公开附件</el-button><p v-if="work.message.value" role="alert">{{work.message.value}}</p><p v-if="!work.busy.value&&selected&&!files.length">尚无本页可选择的公开附件，不能用未知上传或旧方案快照代替。</p><label v-for="f in files" :key="f.fileId"><input type="checkbox" :checked="modelValue.includes(f.fileId)" @change="select(f.fileId,($event.target as HTMLInputElement).checked)"/>{{f.name}} · READY · {{f.size}}字节</label><p v-if="known.some(f=>modelValue.includes(f.fileId))">已显式选择（含其他页/轮次）：{{known.filter(f=>modelValue.includes(f.fileId)).map(f=>f.name).join('、')}}</p><el-pagination v-if="selected" :current-page="page" :total="total" :page-size="20" layout="prev, pager, next, total" @current-change="loadFiles"/></details></template>
